-- Focused owner-isolated regression. No global deletes/reset; all rows roll back.
begin;
select no_plan();
\ir ../support/content-fixture.inc
create temp table ff_fixture as select gen_random_uuid() admin_id,gen_random_uuid() editor_id,gen_random_uuid() ops_id,gen_random_uuid() member_id,gen_random_uuid() editing_id,gen_random_uuid() submitted_id,gen_random_uuid() bad_id,gen_random_uuid() media_id,gen_random_uuid() history_id,gen_random_uuid() baseline_release,(select count(*) from public.content_drafts where status in ('editing','submitted')) base_count,pg_temp.content_boundary_snapshot() snapshot;
grant select on ff_fixture to authenticated;
select diag('owned fixture IDs recorded before mutations: '||row_to_json(f)::text) from (select admin_id,editor_id,ops_id,member_id,editing_id,submitted_id,bad_id,media_id,history_id,base_count from ff_fixture) f;
insert into auth.users(id,email,email_confirmed_at,is_anonymous) select id,'final-fix-'||id||'@example.invalid',now(),false from ff_fixture cross join lateral unnest(array[admin_id,editor_id,ops_id,member_id]) id;
insert into public.staff_memberships(user_id,role) select admin_id,'admin' from ff_fixture union all select editor_id,'editor' from ff_fixture union all select ops_id,'operations' from ff_fixture;
insert into public.content_drafts(id,version,snapshot,status,created_by,updated_by) select editing_id,1,snapshot,'editing',admin_id,admin_id from ff_fixture union all select submitted_id,1,snapshot,'submitted',admin_id,admin_id from ff_fixture;
insert into public.content_releases(id,snapshot,draft_id,draft_version,created_by) select baseline_release,snapshot,editing_id,1,admin_id from ff_fixture;
update public.content_publication set release_id=f.baseline_release from ff_fixture f where singleton;
select set_config('request.jwt.claims',jsonb_build_object('sub',admin_id,'role','authenticated')::text,true) from ff_fixture;
set local role authenticated;
select is((public.get_admin_dashboard()->>'drafts')::bigint,(select base_count+2 from ff_fixture),'admin exact editing plus submitted count');
select set_config('request.jwt.claims',jsonb_build_object('sub',editor_id,'role','authenticated')::text,true) from ff_fixture;
select is((public.get_admin_dashboard()->>'drafts')::bigint,(select base_count+2 from ff_fixture),'editor exact editing plus submitted count');
select throws_ok('select public.get_catalog_workspace()','42501',null,'editor private catalog denied');
select set_config('request.jwt.claims',jsonb_build_object('sub',ops_id,'role','authenticated')::text,true) from ff_fixture;
select is(public.get_admin_dashboard()->'drafts','null'::jsonb,'operations draft count remains hidden');
select lives_ok('select public.get_catalog_workspace()','operations reads private catalog including disabled entries');
select is(jsonb_array_length(public.get_catalog_workspace()->'offerings'),5,'operations receives all five actual SKU entries');
select ok((public.get_catalog_workspace()->'settings') ? 'ordersEnabled','operations sees global gate');
select throws_ok($$select public.set_catalog_offering('11000000-0000-4000-8000-000000000001','USD',100,true,true,0)$$,'42501',null,'operations offering writes denied');
select throws_ok($$select public.update_commerce_settings(false,null,0)$$,'42501',null,'operations settings writes denied');
select set_config('request.jwt.claims',jsonb_build_object('sub',member_id,'role','authenticated')::text,true) from ff_fixture;
select throws_ok('select public.get_catalog_workspace()','42501',null,'member private catalog denied');
select throws_ok('select public.get_admin_dashboard()','42501',null,'failed dashboard access is an error');
reset role;
select lives_ok($$select private.assert_media_selection(snapshot,snapshot) from ff_fixture$$,'unchanged publication can be selected');
select throws_ok($$select private.assert_media_selection(jsonb_set(snapshot,'{media,asset_6f36183e6da5cc73,url}','"/assets/films-20260908/welcome-home.mp4"'),snapshot) from ff_fixture$$,'22023','INVALID_MEDIA','legacy Safari swap rejected at selection');
select throws_ok($$select private.assert_media_snapshot(jsonb_set(snapshot,'{media,asset_6f36183e6da5cc73,url}','"/assets/films-20260908/welcome-home.mp4"')) from ff_fixture$$,'22023','INVALID_MEDIA','legacy Safari swap rejected at publish boundary');
select set_config('request.jwt.claims',jsonb_build_object('sub',admin_id,'role','authenticated')::text,true) from ff_fixture;
set local role authenticated;
select throws_ok($$select public.save_content_draft(bad_id,0,jsonb_set(snapshot,'{media,asset_6f36183e6da5cc73,url}','"/assets/films-20260908/welcome-home.mp4"')) from ff_fixture$$,'22023','INVALID_MEDIA','actual save RPC rejects legacy Safari swap');
reset role;
insert into public.content_drafts(id,version,snapshot,status,created_by,updated_by)
select bad_id,1,jsonb_set(snapshot,'{media,asset_6f36183e6da5cc73,url}','"/assets/films-20260908/welcome-home.mp4"'),'submitted',admin_id,admin_id from ff_fixture;
select public.attest_content_snapshot('draft',d.id,1,d.snapshot,(select active_version from private.content_validation_policy where singleton),f.admin_id) from public.content_drafts d join ff_fixture f on d.id=f.bad_id;
create temp table ff_pointer as select * from public.content_publication;
set local role authenticated;
select throws_ok($$select public.publish_content_draft(bad_id,1) from ff_fixture$$,'22023','INVALID_MEDIA','actual publish RPC rejects attested legacy swap');
reset role;
select is((select row_to_json(p)::text from public.content_publication p),(select row_to_json(p)::text from ff_pointer p),'rejected publication leaves pointer unchanged');
select lives_ok($$select private.assert_media_snapshot(r.snapshot,r.id) from public.content_releases r join public.content_publication p on p.release_id=r.id$$,'proven current historical release remains valid for rollback');
-- Independently owned finalized controlled asset and immutable history fixtures.
insert into public.media_assets(id,created_by,file_name,advertised_size,mime,usage_key,original_path,metadata,release_path,status)
select media_id,admin_id,'final-fix.png',4,'image/png','asset_012d3bf8af92d486','final-fix/'||media_id,'{"mime":"image/png"}', 'final-fix/'||media_id||'/released','ready' from ff_fixture;
insert into storage.objects(bucket_id,name,metadata) select 'media-releases','final-fix/'||media_id||'/released','{"size":4}' from ff_fixture;
create temp table ff_control as select jsonb_set(snapshot,'{media,asset_012d3bf8af92d486}',jsonb_build_object('assetId',media_id,'url','/api/media/'||media_id,'kind','image','profile','public-content','alt','Owned fixture')) snapshot from ff_fixture;
grant select on ff_control to authenticated;
select lives_ok($$select private.assert_media_selection(snapshot,snapshot) from ff_control$$,'finalized controlled replacement remains selectable');
select lives_ok($$select private.assert_media_snapshot(snapshot) from ff_control$$,'finalized controlled replacement remains publishable');
insert into public.content_releases(id,snapshot,draft_id,draft_version,created_by) select f.history_id,c.snapshot,f.editing_id,1,f.admin_id from ff_fixture f cross join ff_control c;
select private.record_media_release(f.history_id,c.snapshot) from ff_fixture f cross join ff_control c;
update public.media_assets set status='archived' where id=(select media_id from ff_fixture);
select lives_ok($$select private.assert_media_selection(snapshot,snapshot) from ff_control$$,'same-slot archived controlled asset inheritance preserved');
select lives_ok($$select private.assert_media_snapshot(c.snapshot,null,f.history_id) from ff_control c cross join ff_fixture f$$,'archived controlled base release inheritance preserved');
select lives_ok($$select private.assert_media_snapshot(c.snapshot,f.history_id) from ff_control c cross join ff_fixture f$$,'proven controlled historical rollback allowed');
select throws_ok($$select private.assert_media_snapshot(jsonb_set(c.snapshot,'{media,asset_6f36183e6da5cc73,url}','"/assets/films-20260908/welcome-home.mp4"'),f.history_id) from ff_control c cross join ff_fixture f$$,'22023','INVALID_MEDIA','history parameter does not authorize untrusted legacy swap');
select public.attest_content_snapshot('release',f.history_id,0,c.snapshot,(select active_version from private.content_validation_policy where singleton),f.admin_id) from ff_fixture f cross join ff_control c;
set local role authenticated;
select lives_ok($$select public.rollback_content_release(history_id) from ff_fixture$$,'actual rollback RPC accepts proven owned historical release inside rollback-only transaction');
reset role;
set local role anon;
select throws_ok('select public.get_catalog_workspace()','42501',null,'anonymous private catalog denied');
reset role;
select * from finish();
rollback;
